import {newCase,questions,moveCase,safeLink} from './workflow.mjs';
import {putFile,getFile,deleteFile,clearFiles,validateFile} from './evidence.mjs';
import {dayKey,makePlan,dailyLoad} from './engine.mjs?v=20261101-journal';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Материал','Обсуждение','Практика','Итог'];
const phases=['material','discussion','practice','complete'];
let api,urls=[],mount=0;
function current(){const s=api.getState();s.cases||=[];return s.cases.find(c=>c.id===s.activeCase)||s.cases[0];}
function ensure(){let c=current();const s=api.getState();if(!c){c=newCase(s.profile,crypto.randomUUID(),dayKey());if(s.review?.note)c.note=s.review.note;s.cases=[c];s.activeCase=c.id;api.save();}else if(c.stage==='material'&&!c.note&&!c.files.length&&!c.link){const p=s.profile;c.focus=p.focus;c.team=p.team;c.mode=p.mode;c.build=p.build;c.role=p.team==='Solo'?'Solo':p.role;api.save();}return c;}
function update(next){const s=api.getState();s.cases=s.cases.map(c=>c.id===next.id?next:c);return api.save();}
const field=(key,label,value,placeholder='',required=true)=>`<div class="field"><label for="case-${key}">${label}</label><textarea id="case-${key}" data-case-field="${key}" maxlength="${['action','measure','next'].includes(key)?1000:3000}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`;
function chat(c){const qs=questions(c),messages=[];
 if(c.stage==='material')messages.push({role:'coach',text:'Начни с материала: опиши один эпизод, приложи результат или короткий клип. Затем нажми «Перейти к обсуждению».'});
 else {messages.push({role:'coach',text:`Разбираем: ${c.focus}. Твоя версия сохранена. ${qs[0]}`});c.answers.forEach((text,i)=>{messages.push({role:'user',text});messages.push({role:'coach',text:i<2?qs[i+1]:'Ответы записаны. Теперь сформулируй одно изменение и способ его проверки в блоке «Что проверишь в игре». Это твоя рабочая гипотеза; автоматический вердикт по файлу пока недоступен.'});});}
 return `<section class="card ws-chat" id="ws-chat"><div class="ws-chat-head"><span class="badge lime">ДИАЛОГ ПО ЭПИЗОДУ</span><h2>Обсуждение эпизода</h2><a href="#coach" class="btn secondary">Открыть AI-чат →</a><p>Здесь — короткий опрос по эпизоду. Для свободного общения открой AI-чат. Файлы автоматически не анализируются.</p></div><div class="ws-messages" role="log" aria-label="Обсуждение эпизода">${messages.map(m=>`<div class="message ${m.role}"><small>${m.role==='user'?'ТЫ':'ПОМОЩНИК · ОПРОС'}</small>${esc(m.text)}</div>`).join('')}</div>${c.stage==='discussion'&&c.answers.length<3?`<form id="ws-answer" class="ws-compose"><label for="ws-message">Твой ответ · вопрос ${c.answers.length+1} из 3</label><textarea id="ws-message" name="answer" maxlength="2000" required placeholder="Коротко, по ситуации. Неизвестное так и обозначь.">${esc(c.answerDraft||'')}</textarea><button class="btn" type="submit">Ответить →</button></form>`:`<div class="ws-compose"><p>${c.stage==='material'?'После добавления описания здесь появится первый вопрос.':c.stage==='discussion'?'Следующий шаг: заполни «Что проверишь в игре».':c.stage==='practice'?'Теперь проверь своё изменение в игре и запиши результат в форме практики.':'Разбор сохранён. Можно открыть новый эпизод.'}</p></div>`}</section>`;
}
function files(c){return `<section class="ws-files"><h3>Клип, скриншот или результат</h3><p>До 3 файлов, суммарно 100 МБ. Для командной игры полезен короткий клип с войсами. Можно начать только с описания.</p><label class="ws-upload">＋ Прикрепить файл<input id="ws-file" type="file" accept=".mp4,.webm,.png,.jpg,.jpeg,.webp,.replay"></label><p class="ws-local">Файлы сохраняются в этом браузере. На сервер не отправляются. .replay хранится как файл, просмотр и разбор не поддерживаются.</p><div id="ws-files">${c.files.map(f=>`<div class="ws-file" data-file-id="${esc(f.id)}"><div class="ws-file-top"><strong>${esc(f.name)}</strong><span>${(f.size/1048576).toFixed(1)} МБ</span><button type="button" class="btn ghost" data-remove-file="${esc(f.id)}" aria-label="Удалить ${esc(f.name)}">Удалить</button></div><div data-preview="${esc(f.id)}"><p>Загрузка локального файла…</p></div></div>`).join('')}</div></section>`;}
export function renderWorkspace(){const c=ensure(),step=phases.indexOf(c.stage),next=['Опиши один момент и добавь материал','Ответь на вопросы и выбери одно изменение','Проверь изменение в игре и запиши результат','Итог сохранён. Выбери следующий эпизод'][step];
 const s=api.getState(),check=s.checkins[dayKey()],light=check&&dailyLoad(check)==='light',minutes=makePlan(s.profile,check||{}).reduce((n,t)=>n+t.minutes,0);
 const loadNote=check?(light?`Сегодня лёгкий режим: ${check.sleep} ч сна, энергия ${check.energy}/5. План — до ${minutes} минут спокойного разбора; игровую практику можно отложить.`:`Сегодня обычный режим: ${check.sleep} ч сна, энергия ${check.energy}/5. На разбор, практику и итог — до ${minutes} минут.`):'Самочувствие сегодня ещё не отмечено. Отметь его в кабинете, чтобы подстроить объём работы.';
 const material=`${c.focus.startsWith('Общий импрув')?'<div class="ws-task"><h2>Начнём без готового диагноза</h2><p>Опиши, как закончились последние несколько игр. Поможем собрать наблюдения и выбрать, что проверить первым. Можно начать со свободного разговора в AI-чате.</p><a href="#coach">Обсудить с AI →</a></div>':''}<form id="ws-material">${field('note','Что произошло и что хочешь разобрать?',c.note,c.focus.startsWith('Общий импрув')?'Как закончились последние игры? Что повторялось? Если пока не понимаешь причину — так и напиши.':'Например: проиграли контест. На 00:42 пошёл в файт, пока тиммейт ещё лутался. Думаю, начали раздельно.')}<div class="field"><label for="case-link">Ссылка на клип или результаты — необязательно</label><input id="case-link" data-case-field="link" type="url" value="${esc(c.link)}" placeholder="https://…"><p>Ссылка сохраняется для открытия вручную. Импорт статистики не подключён.</p></div>${files(c)}<button class="btn" type="submit">Перейти к обсуждению →</button></form>`;
 const source=`<details class="ws-source"><summary>Материал и твоя версия</summary><p class="ws-preserve">${esc(c.note)}</p>${c.link?`<a href="${esc(safeLink(c.link))}" target="_blank" rel="noopener noreferrer">Открыть прикреплённую ссылку ↗</a>`:''}${files(c)}</details>`;
 const practiceForm=`<section><h2>Что проверишь в игре</h2><p>Сформулируй решение, которое зависит от тебя. Укажи условия, при которых оно применимо.</p><form id="ws-practice">${field('action','Одно изменение',c.action,'Например: перед заходом на соперника дождаться подтверждения тиммейта, что он готов к размену.')}${field('measure','Как поймёшь, что выполнил?',c.measure,'Например: после каждого подходящего контеста записать, был ли колл, ответ и совместный заход.')}<button class="btn" type="submit" ${c.answers.length<3?'disabled':''}>Сохранить и перейти к практике →</button>${c.answers.length<3?'<p>Сначала ответь на три вопроса в диалоге.</p>':''}</form></section>`;
 const resultForm=`<div class="ws-task"><span class="badge lime">ТВОЯ ЗАДАЧА В ИГРЕ</span><h2>${esc(c.action)}</h2><p><strong>Проверка:</strong> ${esc(c.measure)}</p></div><form id="ws-finish"><h2>Вернулся с практики?</h2>${field('outcome','Что получилось на практике?',c.outcome,'Сколько подходящих ситуаций было? В скольких выполнил решение? Что помешало? Если не было подходящих ситуаций — запиши это.')}${field('next','Что сделаешь дальше?',c.next,'Повторю проверку с тем же условием / изменю условие / разберу следующий момент…')}<button class="btn" type="submit">Сохранить итог в журнал →</button></form>`;
 const complete=`<span class="badge lime">ИТОГ СОХРАНЁН</span><h2>Один эпизод доведён до результата</h2><dl class="ws-summary"><dt>Что проверял</dt><dd>${esc(c.action)}</dd><dt>Как проверял</dt><dd>${esc(c.measure)}</dd><dt>Твой результат</dt><dd>${esc(c.outcome)}</dd><dt>Следующий шаг</dt><dd>${esc(c.next)}</dd></dl><p>Это твои наблюдения, а не автоматическая оценка скилла.</p><div class="actions"><button class="btn" data-ws-new>Начать следующий разбор →</button><a class="btn secondary" href="#journal">Открыть журнал</a></div>`;
 return `<div class="workspace" data-phase="${c.stage}" data-answered="${c.answers.length===3}"><div class="ws-heading"><div><span class="eyebrow">ТВОЯ ПРАКТИКА · ${esc(c.mode)} · ${esc(c.team)} · ${esc(c.role)}</span><h1>Один момент. Один следующий шаг.</h1><p>Материал, обсуждение и результат — в одном месте.</p></div><a href="#dashboard" class="btn secondary">Самочувствие</a></div><div class="ws-task"><strong>Нагрузка на сегодня</strong><p>${esc(loadNote)}</p></div><ol class="ws-steps" aria-label="Этапы разбора">${names.map((n,i)=>`<li class="${i===step?'current':i<step?'passed':''}" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${n}</li>`).join('')}</ol><div class="ws-next"><strong>Сейчас: ${next}</strong><span id="ws-save-status" role="status">Изменения сохраняются в браузере</span></div><div class="ws-layout"><div class="card ws-work">${c.stage==='material'?material:c.stage==='discussion'?practiceForm:c.stage==='practice'?resultForm:complete}${c.stage!=='material'?source:''}</div>${chat(c)}</div>${history()}${api.getState().messages.length?`<details class="card ws-source"><summary>Диалог из предыдущей версии</summary>${api.getState().messages.map(m=>`<p class="ws-preserve"><strong>${m.role==='user'?'Ты':'Помощник'}:</strong> ${esc(m.text)}</p>`).join('')}</details>`:''}<p class="ws-local">Профиль, разборы и файлы доступны только на этом устройстве и в этом браузере. Экспорт в профиле сохраняет текст, но не медиафайлы.</p></div>`;
}
function history(){const s=api.getState();return s.cases.length>1?`<section class="card ws-history"><h2>Мои разборы</h2>${s.cases.map(c=>`<button class="ws-history-item" data-ws-open="${esc(c.id)}"><span>${esc(c.date)} · ${esc(c.focus)}</span><strong>${esc(c.note.slice(0,90)||'Новый эпизод')}</strong><span>${names[phases.indexOf(c.stage)]} →</span></button>`).join('')}</section>`:'';}
export function releaseWorkspace(){mount++;urls.forEach(u=>URL.revokeObjectURL(u));urls=[];}
export async function mountWorkspace(){const generation=mount,c=current();if(!c||!document.querySelector('.workspace'))return;const log=document.querySelector('.ws-messages');if(log)log.scrollTop=log.scrollHeight;
 for(const f of c.files){const target=document.querySelector(`[data-preview="${f.id}"]`);if(!target)continue;
  try{const row=await getFile(f.id);if(generation!==mount)return;target.replaceChildren();if(!row){target.textContent='Файл недоступен в этом браузере. Прикрепи его заново; текст разбора сохранён.';continue;}const url=URL.createObjectURL(row.file);urls.push(url);let media;
   if(/^image\/(png|jpeg|webp)$/.test(row.file.type)){media=document.createElement('img');media.alt='Скриншот для разбора';}
   else if(/^video\/(mp4|webm)$/.test(row.file.type)){media=document.createElement('video');media.controls=true;media.preload='metadata';}
   if(media){media.src=url;media.className='ws-media';media.addEventListener('error',()=>{const p=document.createElement('p');p.textContent='Браузер не поддерживает воспроизведение этого файла. Его можно скачать.';target.append(p);},{once:true});target.append(media);}
   const a=document.createElement('a');a.href=url;a.download=f.name;a.textContent='Скачать файл';target.append(a);
  }catch{target.textContent='Не удалось открыть локальное хранилище. Текст разбора доступен.';}
 }
}
export function installWorkspace(options){api=options;
 document.addEventListener('input',e=>{const key=e.target.dataset.caseField,c=current();if(!c)return;if(key&&['note','link','action','measure','outcome','next'].includes(key)){c[key]=e.target.value;const ok=api.save();const status=document.querySelector('#ws-save-status');if(status)status.textContent=ok?'Черновик сохранён':'Не удалось сохранить';}if(e.target.id==='ws-message'){c.answerDraft=e.target.value;api.save();}});
 document.addEventListener('submit',e=>{if(!e.target.id.startsWith('ws-'))return;e.preventDefault();const c=current();try{let next;if(e.target.id==='ws-material'){if(c.link&&!safeLink(c.link))throw Error('Укажи HTTPS-ссылку без логина и пароля.');next=moveCase(c,'discuss');}if(e.target.id==='ws-answer'){next=moveCase(c,'answer',{text:new FormData(e.target).get('answer')});delete next.answerDraft;}if(e.target.id==='ws-practice')next=moveCase(c,'practice');if(e.target.id==='ws-finish'){next=moveCase(c,'finish');const s=api.getState();s.sessions.unshift({caseId:c.id,date:dayKey(),type:'Разбор и практика',matches:0,early:0,note:`Проверка: ${c.action}\nКритерий: ${c.measure}\nРезультат: ${c.outcome}\nДальше: ${c.next}`.slice(0,3000)});s.sessions=s.sessions.slice(0,365);}if(next){const ok=update(next);api.render();if(next.stage==='discussion'&&next.answers.length<3)document.querySelector('#ws-message')?.focus();else document.querySelector('.ws-next')?.scrollIntoView({block:'start'});if(ok)api.toast(next.stage==='complete'?'Итог сохранён в журнал. Следующий шаг — на экране.':'Шаг сохранён.');}}catch(error){api.toast(error.message);}});
 document.addEventListener('change',async e=>{if(e.target.id!=='ws-file')return;const file=e.target.files[0],c=current();if(!file||!c)return;const id=crypto.randomUUID(),button=e.target;button.disabled=true;try{validateFile(file,c.files);await putFile(id,file);const live=api.getState().cases?.find(x=>x.id===c.id);if(!live){await deleteFile(id);return;}try{validateFile(file,live.files);}catch(error){await deleteFile(id);throw error;}live.files.push({id,name:file.name,size:file.size,type:file.type});if(!api.save()){live.files.pop();await deleteFile(id);return;}api.render();api.toast('Файл прикреплён и сохранён в этом браузере.');}catch(error){api.toast(error.message?.startsWith('Максимум')||error.message?.startsWith('Поддерживаются')||error.message?.startsWith('В одном')?error.message:'Не удалось сохранить файл: проверь свободное место или разрешения браузера.');}finally{button.disabled=false;button.value='';}});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const c=current(),s=api.getState();if(b.dataset.removeFile){b.disabled=true;try{await deleteFile(b.dataset.removeFile);const live=s.cases?.find(x=>x.id===c.id);if(live)live.files=live.files.filter(f=>f.id!==b.dataset.removeFile);api.save();api.render();}catch{api.toast('Не удалось удалить файл.');b.disabled=false;}}if(b.dataset.wsOpen){s.activeCase=b.dataset.wsOpen;api.save();if(!["#plan","#coach","#review"].includes(location.hash))location.hash="plan";else api.render();window.scrollTo(0,0);}if(b.hasAttribute('data-ws-new')){if(s.cases.length>=30){api.toast('Сохранено 30 разборов. Экспортируй данные перед очисткой в профиле.');return;}const n=newCase(s.profile,crypto.randomUUID(),dayKey());s.cases.unshift(n);s.activeCase=n.id;api.save();api.render();window.scrollTo(0,0);}});
}
export async function resetEvidence(){try{await clearFiles();}catch{api.toast('Текст удалён, но очистить файлы не удалось. Удали данные сайта в настройках браузера.');}}
